// ===========================================================================
//  CẤU HÌNH BACKTEST
// ===========================================================================
const WATCHLIST = ['VNM', 'FPT', 'HPG', 'MWG', 'VCB', 'SSI', 'DGC', 'VND', 'MBB', 'STB'];

const YEARS_BACK  = 3;            // quét bao nhiêu năm lịch sử
const HOLD_DAYS   = 10;           // giữ bao nhiêu phiên sau tín hiệu
const STOP_WINDOW = 20;           // cửa sổ phiên để thử ngưỡng cắt lỗ
const COOLDOWN    = 5;            // tín hiệu cùng loại trên 1 mã cách nhau ít nhất N phiên
const STOP_LEVELS = [5, 7, 9, 11];// các ngưỡng cắt lỗ % cần thử

// Ngưỡng tín hiệu - giống hệ cảnh báo đang chạy
const VOL_SPIKE  = 2.0;
const PRICE_CORE = 3.0;   // %
const PRICE_HOT  = 5.0;   // %
const NET_MIN_TY = 1;     // tỷ đồng
const STREAK_MIN = 3;     // chuỗi khối ngoại
// ===========================================================================

const to   = Math.floor(Date.now() / 1000);
const from = to - YEARS_BACK * 365 * 86400;

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const headers = { 'User-Agent': UA, 'Accept': '*/*' };

const dateOf = (unix) => new Date(unix * 1000).toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });

// Nguồn giá: DNSE chính, VNDirect dự phòng (mảng song song t/o/h/l/c/v, cũ -> mới)
const fetchBars = async (ticker) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock',
      qs: { symbol: ticker, from, to, resolution: '1D' },
      headers, json: true, timeout: 25000,
    });
    if (res && Array.isArray(res.t) && res.t.length) return { src: 'DNSE', d: res };
  } catch (e) { /* dự phòng */ }
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://dchart-api.vndirect.com.vn/dchart/history',
    qs: { symbol: ticker, resolution: 'D', from, to },
    headers: { ...headers, Referer: 'https://dchart.vndirect.com.vn/' },
    json: true, timeout: 25000,
  });
  if (res && Array.isArray(res.t) && res.t.length) return { src: 'VNDirect', d: res };
  throw new Error('cả 2 nguồn giá đều không có dữ liệu');
};

// Khối ngoại: VNDirect finfo, thử size lớn trước
const fetchFlows = async (ticker) => {
  const h = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };
  for (const size of [800, 100]) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + ticker + '&size=' + size + '&sort=tradingDate:desc',
        headers: h, json: true, timeout: 25000,
      });
      const data = (res && res.data) || [];
      if (data.length) return data;
    } catch (e) { /* thử size nhỏ hơn */ }
  }
  return [];
};

const debug = [];
const rets = { s1: [], s2: [], s3: [], s4: [], s5: [], s6: [], base: [] };
const stopStats = STOP_LEVELS.map(sl => ({ sl, n: 0, hit: 0, sum: 0 }));
const noStop = { n: 0, sum: 0 };
let firstDate = '9999-99-99', lastDate = '';
let flowMinCount = Infinity, flowOldest = '0000-00-00';

for (const ticker of WATCHLIST) {
  try {
    const { src, d } = await fetchBars(ticker);
    const n = d.t.length;
    if (n < 60) { debug.push(ticker + ': chỉ ' + n + ' phiên, bỏ qua'); continue; }
    if (dateOf(d.t[0]) < firstDate) firstDate = dateOf(d.t[0]);
    if (dateOf(d.t[n - 1]) > lastDate) lastDate = dateOf(d.t[n - 1]);

    const flowsArr = await fetchFlows(ticker);
    const flows = {};
    for (const f of flowsArr) flows[f.tradingDate] = (f.netVal || 0) / 1e9;
    if (flowsArr.length) {
      flowMinCount = Math.min(flowMinCount, flowsArr.length);
      const oldest = flowsArr[flowsArr.length - 1].tradingDate || '';
      if (oldest > flowOldest) flowOldest = oldest;
    }

    const t = d.t, o = d.o, c = d.c, l = d.l, v = d.v;

    // Vào lệnh = giá MỞ CỬA phiên kế tiếp (nhận cảnh báo hôm nay, mua sáng mai)
    const evalTrade = (i) => {
      const ei = i + 1, xi = i + 1 + HOLD_DAYS;
      if (xi >= n || !o[ei] || !c[xi]) return null;
      return c[xi] / o[ei] - 1;
    };

    const stopTest = (i) => {
      const ei = i + 1, xi = i + 1 + STOP_WINDOW;
      if (xi >= n || !o[ei] || !c[xi]) return;
      const entry = o[ei];
      const endRet = c[xi] / entry - 1;
      noStop.n++; noStop.sum += endRet;
      for (const s of stopStats) {
        const lvl = entry * (1 - s.sl / 100);
        let stopped = false;
        for (let k = ei + 1; k <= xi; k++) { if (l[k] && l[k] <= lvl) { stopped = true; break; } }
        s.n++;
        if (stopped) { s.hit++; s.sum += -s.sl / 100; } else { s.sum += endRet; }
      }
    };

    const lastFire = { s1: -99, s2: -99, s3: -99, s4: -99, s5: -99, s6: -99 };
    const fire = (key, i) => {
      if (i - lastFire[key] < COOLDOWN) return;
      lastFire[key] = i;
      const r = evalTrade(i);
      if (r !== null) rets[key].push(r);
      if (key === 's1') stopTest(i);
    };

    let run = 0, prevSign = 0;
    for (let i = 21; i < n; i++) {
      let sumV = 0;
      for (let k = i - 20; k < i; k++) sumV += v[k] || 0;
      const avgV = sumV / 20;
      const pct = c[i - 1] ? (c[i] / c[i - 1] - 1) * 100 : 0;
      const spike = avgV > 0 && v[i] >= VOL_SPIKE * avgV;

      if (spike && pct >= PRICE_CORE) fire('s1', i);
      if (spike)                      fire('s2', i);
      if (pct >= PRICE_HOT)           fire('s3', i);
      if (pct <= -PRICE_CORE)         fire('s4', i);

      const net = flows[dateOf(t[i])];
      const sgn = net === undefined ? 0 : net >= NET_MIN_TY ? 1 : net <= -NET_MIN_TY ? -1 : 0;
      run = (sgn !== 0 && sgn === prevSign) ? run + 1 : (sgn !== 0 ? 1 : 0);
      prevSign = sgn;
      if (run === STREAK_MIN && sgn === 1)  fire('s5', i);
      if (run === STREAK_MIN && sgn === -1) fire('s6', i);

      const r = evalTrade(i);
      if (r !== null) rets.base.push(r);
    }

    debug.push(ticker + ': OK (' + src + ', ' + n + ' phiên giá, ' + flowsArr.length + ' phiên KN)');
  } catch (e) {
    debug.push(ticker + ': ❌ ' + (e.message || String(e)));
  }
}

// ----------------- Thống kê & soạn báo cáo -----------------
const stat = (arr) => {
  if (!arr.length) return null;
  const nWin = arr.filter(r => r > 0).length;
  const avg = arr.reduce((a, b) => a + b, 0) / arr.length;
  let worst = arr[0];
  for (const r of arr) if (r < worst) worst = r;
  return { count: arr.length, win: 100 * nWin / arr.length, avg: 100 * avg, worst: 100 * worst };
};

const fmtP = (x) => (x >= 0 ? '+' : '') + x.toFixed(1) + '%';
const base = stat(rets.base);

const line = (s) => s
  ? s.count + ' lần · thắng ' + s.win.toFixed(0) + '% · TB ' + fmtP(s.avg) + ' · tệ nhất ' + fmtP(s.worst) + (s.count < 15 ? ' _(mẫu nhỏ)_' : '')
  : '_không đủ dữ liệu_';

const verdict = (s, invert) => {
  if (!s || !base) return '';
  const dAvg = s.avg - base.avg;
  if (invert) {
    if (dAvg <= -1) return '\n→ ✅ đúng vai cảnh báo: sau tín hiệu này giá đi kém hẳn nền';
    return '\n→ ➖ chưa thấy khác biệt rõ so với nền';
  }
  if (dAvg >= 1 && s.win >= base.win + 3) return '\n→ ✅ tốt hơn nền rõ rệt — đáng tin';
  if (dAvg <= -1) return '\n→ 🔻 kém hơn nền — cân nhắc bỏ tín hiệu này';
  return '\n→ ➖ không khác nền đáng kể';
};

let message = '';
if (!base) {
  message = '⚠️ *BACKTEST THẤT BẠI* — không lấy được dữ liệu giá.\n\n' + debug.join('\n');
} else {
  const secs = [];
  secs.push('*1️⃣ Phá vỡ: KL x' + VOL_SPIKE + ' + giá tăng ≥' + PRICE_CORE + '%*\n' + line(stat(rets.s1)) + verdict(stat(rets.s1), false));
  secs.push('*2️⃣ KL đột biến x' + VOL_SPIKE + ' (mọi hướng)*\n' + line(stat(rets.s2)) + verdict(stat(rets.s2), false));
  secs.push('*3️⃣ Giá tăng ≥' + PRICE_HOT + '% (ngưỡng nhóm sóng)*\n' + line(stat(rets.s3)) + verdict(stat(rets.s3), false));
  secs.push('*4️⃣ Giá giảm ≥' + PRICE_CORE + '% (thử "bắt dao rơi")*\n' + line(stat(rets.s4)) + verdict(stat(rets.s4), false));
  secs.push('*5️⃣ Khối ngoại GOM ≥' + STREAK_MIN + ' phiên*\n' + line(stat(rets.s5)) + verdict(stat(rets.s5), false));
  secs.push('*6️⃣ Khối ngoại XẢ ≥' + STREAK_MIN + ' phiên*\n' + line(stat(rets.s6)) + verdict(stat(rets.s6), true));
  secs.push('*⚖️ NỀN CHUNG (mua bất kỳ phiên nào)*\n' + line(base) + '\n→ Tín hiệu có giá trị phải THẮNG được nền này.');

  if (noStop.n) {
    let bestAvg = -Infinity;
    for (const s of stopStats) { const a = s.sum / s.n; if (a > bestAvg) bestAvg = a; }
    const stopLines = stopStats.map(s => {
      const a = s.sum / s.n;
      return '• Cắt ' + s.sl + '%: dính ' + (100 * s.hit / s.n).toFixed(0) + '% số lần · kết quả TB ' + fmtP(100 * a) + (a === bestAvg ? ' ⭐' : '');
    }).join('\n');
    secs.push('*🛑 QUÉT NGƯỠNG CẮT LỖ* — sau tín hiệu phá vỡ (1️⃣), cửa sổ ' + STOP_WINDOW + ' phiên, ' + noStop.n + ' lần\n'
      + stopLines
      + '\n• Không cắt lỗ: kết quả TB ' + fmtP(100 * noStop.sum / noStop.n)
      + '\n→ ⭐ = ngưỡng giữ tiền tốt nhất trong quá khứ');
  }

  const flowNote = isFinite(flowMinCount)
    ? 'Khối ngoại: ~' + flowMinCount + ' phiên gần nhất/mã (từ ' + flowOldest.split('-').reverse().join('/') + ')'
    : 'Khối ngoại: không có dữ liệu';

  message = '📋 *BACKTEST ' + YEARS_BACK + ' NĂM — ' + WATCHLIST.length + ' MÃ WATCHLIST*\n'
    + '_Giá: ' + firstDate.split('-').reverse().join('/') + ' → ' + lastDate.split('-').reverse().join('/') + ' · ' + flowNote + '_\n'
    + '_Vào lệnh giá mở cửa phiên kế tiếp · giữ ' + HOLD_DAYS + ' phiên · tín hiệu cùng loại cách nhau ≥' + COOLDOWN + ' phiên_\n\n'
    + secs.join('\n\n———\n\n')
    + '\n\n⚠️ _Quá khứ không đảm bảo tương lai. Chưa tính phí, trượt giá, T+2.5. Dùng để LOẠI luật tệ và đặt kỳ vọng đúng — không phải máy in tiền._';
}

return [{ json: { message, debug } }];

// Cắt báo cáo thành các đoạn <= 3800 ký tự cho vừa giới hạn Telegram
const full = $input.first().json.message || '⚠️ Không có nội dung báo cáo.';
const SIZE = 3800;
const parts = [];
let s = full;
while (s.length > SIZE) {
  let cut = s.lastIndexOf('\n', SIZE);
  if (cut < SIZE * 0.5) cut = SIZE;
  parts.push(s.slice(0, cut));
  s = s.slice(cut);
}
if (s.trim()) parts.push(s);
return parts.map(p => ({ json: { message: p } }));
